import{_ as t}from"./chunks/the-brick-the-editor-the-referee.CS-byB8y.js";import{_ as a,o as r,c as o,aa as n}from"./chunks/framework.CuTukyzC.js";import"./chunks/theme.jdWPvDJU.js";const m=JSON.parse('{"title":"The brick, the editor, and the referee","description":"The whole story in small words — a one-kilobyte brick, an editor that AI agents built out of it, and the referee that makes AI-built software safe to trust.","frontmatter":{"title":"The brick, the editor, and the referee","description":"The whole story in small words — a one-kilobyte brick, an editor that AI agents built out of it, and the referee that makes AI-built software safe to trust.","date":"2026-07"},"headers":[],"relativePath":"blog/the-brick-the-editor-the-referee.md","filePath":"blog/the-brick-the-editor-the-referee.md","lastUpdated":1786402255000}'),s={name:"blog/the-brick-the-editor-the-referee.md"};function i(h,e,l,d,c,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="the-brick-the-editor-and-the-referee" tabindex="-1">The brick, the editor, and the referee <a class="header-anchor" href="#the-brick-the-editor-and-the-referee" aria-label="Permalink to &quot;The brick, the editor, and the referee&quot;">​</a></h1><p><img src="'+t+'" alt="The brick, the editor, and the referee"></p><p>Most posts on this blog argue. This one just tells the story, in the smallest words we can find — because when we stepped back and looked at what had actually happened, the simple version turned out to be the honest one.</p><h2 id="_1-the-brick" tabindex="-1">1. The brick <a class="header-anchor" href="#_1-the-brick" aria-label="Permalink to &quot;1. The brick&quot;">​</a></h2><p>Most software is built out of tangled stuff — knots of state, frameworks, and glue. <a href="/guide/introduction">ivue</a> is a brick: about <a href="/blog/one-kilobyte-feature">a kilobyte</a> of engine that lets you build out of <strong>plain classes</strong> that snap together and update themselves when anything changes. And the blocks never tangle — <a href="/blog/the-object-graph-they-took">no matter how deep you stack them</a>, no matter which file references which, the connections cannot knot.</p><p>That &quot;never tangles&quot; property looks like a convenience. It is the superpower everything below stands on.</p><h2 id="_2-the-editor" tabindex="-1">2. The editor <a class="header-anchor" href="#_2-the-editor" aria-label="Permalink to &quot;2. The editor&quot;">​</a></h2><p>To prove the brick, we built something big out of it: <a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">Invar</a>, a real code editor that runs in a terminal — file tree, tabs, git panel with side-by-side diffs, language intelligence, an integrated terminal. It is fast, it is small, and it is used daily.</p><p>Here is the strange part: <a href="/blog/agents-built-an-editor">AI agents wrote almost all of it</a>. The human&#39;s job was to state the <strong>rules that must never break</strong> — each module carries a written contract of them — and a <strong>referee</strong> checks every change against those rules by actually driving the editor and reading its screen, before anything is allowed in. Agents built features overnight. The referee rejected what broke the rules. The codebase stayed clean — measurably: zero tangles, one cache, after hundreds of commits.</p><p>Rules, plus a referee, plus untangleable bricks. That combination is the discovery.</p><h2 id="_3-the-toy-box-that-builds-toys" tabindex="-1">3. The toy box that builds toys <a class="header-anchor" href="#_3-the-toy-box-that-builds-toys" aria-label="Permalink to &quot;3. The toy box that builds toys&quot;">​</a></h2><p>Then something unplanned happened. An AI coding assistant was run <em>inside</em> the editor&#39;s new terminal — and it became obvious that the editor already had every part an AI assistant&#39;s <strong>home</strong> needs: a place to talk, panes to show work in, overlay dialogs for questions, and eyes into the code itself.</p><p>So the next blueprint wrote itself, and it rests on one idea: an AI assistant should not be a wall of text you <em>trust</em>. It should be a colleague that <strong>shows you</strong> — the change as a real diff, the file opened at the real line, the test that proves it, the work happening live as it happens, replayable tomorrow. Reading its work and verifying its work become the same act.</p><p>Slop — AI output that merely <em>looks</em> right — survives only where checking is expensive. Make showing cheap and slop loses its habitat.</p><h2 id="_4-doors-that-open-both-ways" tabindex="-1">4. Doors that open both ways <a class="header-anchor" href="#_4-doors-that-open-both-ways" aria-label="Permalink to &quot;4. Doors that open both ways&quot;">​</a></h2><p>The same blueprint gives the human a door policy. Every action the AI wants to take arrives as a <strong>question in data</strong>: let reads through automatically, make writes ask, forbid the dangerous things entirely — or require that the referee is happy before a change may even be committed. A second AI can answer the first one&#39;s routine questions, so only real judgment reaches a person. Every answer is recorded.</p><p>And the doors open the other way too: the AI can use the editor&#39;s own eyes and hands — ask the language server what a type really is, look at the actual rendered screen, run the actual tests — to <strong>prove its work instead of describing it</strong>. The human governs the machine; the machine shows its homework; the referee checks them both.</p><h2 id="_5-the-toy-that-makes-new-toys" tabindex="-1">5. The toy that makes new toys <a class="header-anchor" href="#_5-the-toy-that-makes-new-toys" aria-label="Permalink to &quot;5. The toy that makes new toys&quot;">​</a></h2><p>The last unlock follows from the others. Because the rules and the referee ship <em>inside</em> the box, anyone who has the editor can simply ask it for a new feature — and their AI builds it under the same contracts, checked by the same referee, in the same untangleable bricks. Good pieces can flow back to everyone, carrying their evidence with them: a contribution is reviewable because it <em>arrives</em> with its contract, its test, and its green referee run.</p><p>Software that grows by conversation — and cannot drift while growing. The editor is named <a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">Invar</a> after the alloy engineered not to expand under heat. The name is the whole thesis.</p><h2 id="in-one-breath" tabindex="-1">In one breath <a class="header-anchor" href="#in-one-breath" aria-label="Permalink to &quot;In one breath&quot;">​</a></h2><p>Write down the rules that must never break. Give the rules a referee. Build out of bricks that cannot tangle. Then AI can build almost everything else — fast, in parallel, overnight — and you can <em>watch and check</em> instead of trust. The kilobyte made the editor possible; the editor makes the AI&#39;s house possible; and a house with rules, evidence, and a referee is the first one worth letting the machines build in.</p><p>The brick is <a href="https://www.npmjs.com/package/ivue" target="_blank" rel="noreferrer">on npm</a>. The editor is <a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">on GitHub</a>. The referee runs on every commit.</p>',23)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
